package app.flow.player;
import android.content.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;
/** Public lead paragraphs only; detailed Plot sections are never requested. */
final class MovieInfo {
 static String enc(String value)throws Exception{return URLEncoder.encode(value,"UTF-8");}
 static JSONObject get(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(12000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","FlowPersonalMedia/1.2 (Android; movie introductions)");try{if(c.getResponseCode()!=200)throw new IOException("Metadata unavailable");try(InputStream in=c.getInputStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){bytes.write(b,0,n);if(bytes.size()>2*1024*1024)throw new IOException("Metadata too large");}return new JSONObject(bytes.toString("UTF-8"));}}finally{c.disconnect();}}
 static String normal(String s){return s.toLowerCase(Locale.ROOT).replace("&"," and ").replaceAll("\\([^)]*\\)","").replaceAll("[^\\p{L}\\p{N}]+"," ").trim();}
 static JSONObject best(JSONObject response,String query,String year)throws Exception{JSONObject pages=response.optJSONObject("query");if(pages==null)return null;pages=pages.optJSONObject("pages");if(pages==null)return null;JSONObject best=null;double scoreBest=0;Iterator<String> keys=pages.keys();Set<String> words=new HashSet<>(Arrays.asList(normal(query).split(" +")));while(keys.hasNext()){JSONObject page=pages.getJSONObject(keys.next());String title=page.optString("title"),intro=page.optString("extract");JSONObject props=page.optJSONObject("pageprops");if(page.has("missing")||intro.isEmpty()||(props!=null&&props.has("disambiguation"))||title.startsWith("List of"))continue;String n=normal(title);double score=n.equals(normal(query))?10:0;int matches=0;for(String word:words)if(n.contains(word))matches++;score+=5d*matches/Math.max(1,words.size());String first=intro.substring(0,Math.min(450,intro.length())).toLowerCase(Locale.ROOT);if(first.contains("film")||first.contains("series"))score+=2;else score-=5;if(!year.isEmpty()){if(first.contains(year)||title.contains(year))score+=5;else if(first.matches("(?s).*\\b(?:19|20)\\d{2}\\b.*"))score-=12;}if(score>scoreBest&&matches>=Math.max(1,Math.ceil(words.size()*.65))){scoreBest=score;best=page;}}return scoreBest>=7?best:null;}
 static JSONObject lookup(Context context,String raw,String year)throws Exception{String key=raw.toLowerCase(Locale.ROOT)+"|"+year;SharedPreferences cache=context.getSharedPreferences("movie-info",0);String cached=cache.getString(key,null);if(cached!=null&&System.currentTimeMillis()-cache.getLong("checked:"+key,0)<CachePolicy.WEEK)return new JSONObject(cached).put("cached",true);JSONObject result=fetch(raw,year);if(result.optBoolean("found")){SharedPreferences.Editor editor=cache.edit();if(cache.getAll().size()>120)editor.clear();editor.putString(key,result.toString()).putLong("checked:"+key,System.currentTimeMillis()).apply();}return result;}
 static JSONObject fetch(String raw,String year)throws Exception{
  String query=raw.trim();if(query.isEmpty()||query.length()>180)throw new IllegalArgumentException("Invalid title");year=year.matches("(?:19|20)\\d{2}")?year:"";
  String props="&prop=extracts%7Cpageprops%7Cpageimages%7Cinfo&exintro=1&explaintext=1&exsentences=3&piprop=thumbnail&pithumbsize=500&inprop=url";
  String candidates=query+"|"+query+" (film)"+(year.isEmpty()?"":"|"+query+" ("+year+" film)");JSONObject response=get("https://en.wikipedia.org/w/api.php?action=query&format=json&redirects=1&titles="+enc(candidates)+props);JSONObject page=best(response,query,year);
  if(page==null){response=get("https://en.wikipedia.org/w/api.php?action=query&format=json&generator=search&gsrnamespace=0&gsrlimit=5&gsrsearch="+enc(query+" "+year+" film")+props);page=best(response,query,year);}
  if(page==null)return new JSONObject().put("found",false).put("message","No confident movie match was found. The filename may differ from the official title.");
  String summary=page.getString("extract").replaceAll("\\s+"," ").trim();if(summary.length()>850){int end=summary.lastIndexOf(". ",850);summary=summary.substring(0,end>120?end+1:summary.lastIndexOf(' ',850))+ (end>120?"":"…");}
  JSONObject result=new JSONObject().put("found",true).put("title",page.getString("title")).put("summary",summary).put("source","Wikipedia").put("sourceURL",page.optString("fullurl","https://en.wikipedia.org/?curid="+page.optLong("pageid"))).put("license","CC BY-SA 4.0").put("note","Introductory text only; no Plot section is fetched.");
  JSONObject thumb=page.optJSONObject("thumbnail");if(thumb!=null)result.put("poster",thumb.optString("source"));
  JSONObject pageprops=page.optJSONObject("pageprops");if(pageprops!=null){result.put("description",pageprops.optString("wikibase-shortdesc"));String entity=pageprops.optString("wikibase_item");if(entity.matches("Q[0-9]+"))try{addFacts(result,entity);}catch(Exception ignored){}}
  return result;
 }
 static String claim(JSONObject claims,String property){try{return claims.getJSONArray(property).getJSONObject(0).getJSONObject("mainsnak").getJSONObject("datavalue").getJSONObject("value").optString("id");}catch(Exception ignored){return "";}}
 static void addFacts(JSONObject result,String entity)throws Exception{JSONObject response=get("https://www.wikidata.org/w/api.php?action=wbgetentities&format=json&props=claims&ids="+entity);JSONObject claims=response.getJSONObject("entities").getJSONObject(entity).getJSONObject("claims");String director=claim(claims,"P57"),genre=claim(claims,"P136");ArrayList<String> actors=new ArrayList<>();JSONArray cast=claims.optJSONArray("P161");if(cast!=null)for(int i=0;i<Math.min(5,cast.length());i++)try{actors.add(cast.getJSONObject(i).getJSONObject("mainsnak").getJSONObject("datavalue").getJSONObject("value").getString("id"));}catch(Exception ignored){}
  try{String runtime=claims.getJSONArray("P2047").getJSONObject(0).getJSONObject("mainsnak").getJSONObject("datavalue").getJSONObject("value").getString("amount");result.put("runtime",Math.round(Double.parseDouble(runtime))+" min");}catch(Exception ignored){}
  try{String imdb=claims.getJSONArray("P345").getJSONObject(0).getJSONObject("mainsnak").getJSONObject("datavalue").getString("value");if(imdb.matches("tt[0-9]+"))result.put("imdbId",imdb);}catch(Exception ignored){}
  ArrayList<String> ids=new ArrayList<>(actors);if(!director.isEmpty())ids.add(director);if(!genre.isEmpty())ids.add(genre);if(ids.isEmpty())return;JSONObject labels=get("https://www.wikidata.org/w/api.php?action=wbgetentities&format=json&props=labels&languages=en&ids="+enc(String.join("|",ids))).getJSONObject("entities");if(!director.isEmpty())result.put("director",label(labels,director));if(!genre.isEmpty())result.put("genre",label(labels,genre));JSONArray names=new JSONArray();for(String id:actors){String value=label(labels,id);if(!value.isEmpty())names.put(value);}result.put("cast",names);
 }
 static String label(JSONObject entities,String id){try{return entities.getJSONObject(id).getJSONObject("labels").getJSONObject("en").getString("value");}catch(Exception ignored){return "";}}
}
